{"items":[{"id":"cap-v2-replacement-ordering_and_selection-typescript-repair-01","test_code":"import { selectRestocks } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) {
    throw new Error(message);
  }
}

function assertDeepEqual(actual: unknown, expected: unknown, message: string): void {
  const actualText = JSON.stringify(actual);
  const expectedText = JSON.stringify(expected);
  assert(
    actualText === expectedText,
    `${message}\nexpected: ${expectedText}\nactual:   ${actualText}`,
  );
}

assertDeepEqual(
  selectRestocks(
    [
      'AB12,5,10',
      'CD34,9,20',
      'EF56,9,3',
      'GH78,5,2',
    ],
    3,
  ),
  [
    { sku: 'EF56', urgency: 9, onHand: 3 },
    { sku: 'CD34', urgency: 9, onHand: 20 },
    { sku: 'GH78', urgency: 5, onHand: 2 },
  ],
  'ranks by urgency descending and then onHand ascending, respecting limit',
);

assertDeepEqual(selectRestocks([], 5), [], 'accepts an empty input');
assertDeepEqual(selectRestocks(['AB,9,0'], 0), [], 'a zero limit returns no candidates');

assertDeepEqual(
  selectRestocks(
    [
      'A,9,0',
      'ABCDEFGHI,9,0',
      'aB,9,0',
      'A_,9,0',
      'AB,10,0',
      'AB,-1,0',
      'AB,1,-1',
      'AB,1,+1',
      'AB,1,01',
      'AB,1,1.0',
      ' AB,1,1',
      'AB,1,1 ',
      'AB,1',
      'AB,1,1,extra',
      'AB,,1',
      'AB,1,',
      'AB,1,9007199254740992',
      'AB,1,0',
      'A2345678,9,9007199254740991',
    ],
    20,
  ),
  [
    { sku: 'A2345678', urgency: 9, onHand: 9007199254740991 },
    { sku: 'AB', urgency: 1, onHand: 0 },
  ],
  'ignores every malformed line and accepts valid boundary forms',
);

assertDeepEqual(
  selectRestocks(
    [
      'Z9,7,4',
      'A1,7,4',
      'M5,7,4',
      'B2,8,10',
    ],
    4,
  ),
  [
    { sku: 'B2', urgency: 8, onHand: 10 },
    { sku: 'Z9', urgency: 7, onHand: 4 },
    { sku: 'A1', urgency: 7, onHand: 4 },
    { sku: 'M5', urgency: 7, onHand: 4 },
  ],
  'breaks complete ranking ties by original position rather than SKU',
);

assertDeepEqual(
  selectRestocks(
    [
      'ZX,6,2',
      'ZX,6,2',
      'AA,6,2',
      'ZX,6,2',
    ],
    10,
  ),
  [
    { sku: 'ZX', urgency: 6, onHand: 2 },
    { sku: 'ZX', urgency: 6, onHand: 2 },
    { sku: 'AA', urgency: 6, onHand: 2 },
    { sku: 'ZX', urgency: 6, onHand: 2 },
  ],
  'preserves duplicate candidates separately and retains stable input order',
);

const invalidLimits = [
  -1,
  1.5,
  Number.NaN,
  Number.POSITIVE_INFINITY,
  Number.NEGATIVE_INFINITY,
  Number.MAX_SAFE_INTEGER + 1,
];
for (const invalidLimit of invalidLimits) {
  assertDeepEqual(
    selectRestocks(['AB,9,0'], invalidLimit),
    [],
    `returns empty for invalid limit ${String(invalidLimit)}`,
  );
}

assertDeepEqual(
  selectRestocks(['AB,0,0'], Number.MAX_SAFE_INTEGER),
  [{ sku: 'AB', urgency: 0, onHand: 0 }],
  'accepts the maximum safe integer as a limit and zero-valued fields',
);

const originalLines: readonly string[] = [
  'ZZ,1,8',
  'AA,9,2',
  'MM,9,1',
  'bad line',
];
const snapshot = originalLines.slice();
selectRestocks(originalLines, 3);
assertDeepEqual(originalLines, snapshot, 'does not mutate the input array');
"}]}

